From 5a5ccceb13715703f610cfc67a6877414db9511b Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 10:42:22 +0100
Subject: [PATCH] applets/taskmanager: show media controls only on the window
 playing

Ungrouped task tooltips showed the media controls on every window of the
same process, such as all windows and web apps of a browser. Now, if one
of its windows has the track in its title, only that one shows them.

BUG: 504234
---
 applets/taskmanager/qml/ToolTipDelegate.qml | 21 +++++++++++++++++++++
 applets/taskmanager/qml/ToolTipInstance.qml |  4 ++--
 2 files changed, 23 insertions(+), 2 deletions(-)

diff --git a/applets/taskmanager/qml/ToolTipDelegate.qml b/applets/taskmanager/qml/ToolTipDelegate.qml
index 014e954c5c..902d20fb32 100644
--- a/applets/taskmanager/qml/ToolTipDelegate.qml
+++ b/applets/taskmanager/qml/ToolTipDelegate.qml
@@ -19,6 +19,7 @@ import org.kde.plasma.private.mpris as Mpris
 import org.kde.kirigami as Kirigami

 import org.kde.plasma.plasmoid
+import org.kde.taskmanager as TaskManager

 Loader {
     id: toolTipDelegate
@@ -82,6 +83,26 @@ Loader {
             virtualDesktops: toolTipDelegate.virtualDesktops
             activities: toolTipDelegate.activities
             model: null
+
+            // Other windows of the same process share its player, so check whether one of them is the one playing
+            hasTrackInATitle: {
+                const track = toolTipDelegate.playerData?.track ?? "";
+                if (!toolTipDelegate.isWin || track === "") {
+                    return false;
+                }
+                for (let i = 0; i < tasksModel.count; ++i) {
+                    const parentIndex = tasksModel.makeModelIndex(i);
+                    const childCount = tasksModel.rowCount(parentIndex);
+                    for (let j = 0; j < Math.max(childCount, 1); ++j) {
+                        const index = childCount > 0 ? tasksModel.makeModelIndex(i, j) : parentIndex;
+                        if (tasksModel.data(index, TaskManager.AbstractTasksModel.AppPid) === toolTipDelegate.pidParent
+                            && String(tasksModel.data(index, Qt.DisplayRole)).includes(track)) {
+                            return true;
+                        }
+                    }
+                }
+                return false;
+            }
         }
     }

diff --git a/applets/taskmanager/qml/ToolTipInstance.qml b/applets/taskmanager/qml/ToolTipInstance.qml
index 5a42d24a17..e0c43b088e 100644
--- a/applets/taskmanager/qml/ToolTipInstance.qml
+++ b/applets/taskmanager/qml/ToolTipInstance.qml
@@ -405,7 +405,7 @@ ColumnLayout {
         // when the instance is going to be destroyed
         active: (toolTipDelegate.parentTask?.tooltipControlsEnabled
              && toolTipDelegate.playerData
-             && ((root.hasTrackInATitle && albumArtImage.available) || (!root.hasTrackInATitle && root.index == 0))) ?? false
+             && (root.hasTrackInATitle ? root.titleIncludesTrack : root.index == 0)) ?? false

         asynchronous: true
         visible: active
@@ -427,7 +427,7 @@ ColumnLayout {
              // Only load for one entry, as the controls only apply to one window.
              // If this is changed in the future, test for index != -1 to avoid loading
              // when the instance is going to be destroyed
-             && ((hasTrackInATitle && albumArtImage.available) || (!hasTrackInATitle && root.index == 0))
+             && (root.hasTrackInATitle ? root.titleIncludesTrack : root.index == 0)
         asynchronous: true
         visible: active
         Layout.fillWidth: true
-- 
